mapping={old:i+1 for i,old in enumerate(order)}
def renumber(text):return re.sub(r'\[(\d+)\]',lambda m:'['+str(mapping[int(m.group(1))])+']',text)
for b in blocks:
    for k in ['text','caption']:
        if k in b:b[k]=renumber(b[k])
    if b['type']=='table':b['rows']=[[renumber(str(v)) for v in row] for row in b['rows']]
def reference(r,num):
    authors=', '.join(r['authors']) if len(r['authors'])<=6 else r['authors'][0]+' et al.'
    s=f'[{num}] {authors}, “{r["title"]},” {r["venue"]}'
    for key,label in [('volume','vol.'),('issue','no.'),('pages','pp.'),('article_number','Art. no.'),('version','V')]:
        if r.get(key):s+=f', {label} {r[key]}'
    if r.get('year'):s+=f', {r["year"]}'
    if r.get('doi'):s+=f', doi: {r["doi"]}.'
    else:
        accessed=date.fromisoformat(r.get('accessed','2026-10-01')).strftime('%-d %B %Y')
        s+=f'. [Online]. Available: {r["url"]}. Accessed: {accessed}.'
    return s
